window.kbPageData["views/entry/k-e50aa174141c7843"] = {"key":"entry/k-e50aa174141c7843","state":{"route":"entry/k-e50aa174141c7843"},"node":{"id":"k-e50aa174141c7843","mode":"k","title":"第二轮土地承包到期后再延长三十年整省试点","type":"制度与规则","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["rural"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"1.第二轮土地承包到期后再延长三十年整省试点\n我国农村土地承包经营制度始于上世纪 80 年代，先后经历过两轮承包，第一轮承包期\n为 1983-1997 年，为期 15 年。到期后国家提出延长承包期，第二轮承包期为 30 年，即\n1997-2027 年。2017 年，党的十九大报告明确提出，“保持土地…","sources":[{"id":"39b3c738fc3895eb","label":"第二轮土地承包到期后再延长三十年整省试点","topic":"年度政府工作","category":"时政","text":"1.第二轮土地承包到期后再延长三十年整省试点\n我国农村土地承包经营制度始于上世纪 80 年代，先后经历过两轮承包，第一轮承包期\n为 1983-1997 年，为期 15 年。到期后国家提出延长承包期，第二轮承包期为 30 年，即\n1997-2027 年。2017 年，党的十九大报告明确提出，“保持土地承包关系稳定并长久不变，\n第二轮土地承包到期后再延长三十年。”坚持“大稳定、小调整”，有序推进第二轮土地\n承包到期后再延长三十年试点，扩大整省试点范围，妥善化解延包中的矛盾纠纷，确保绝大\n多数农户承包地总体顺延、保持稳定。","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":36,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-e50aa174141c7843":[]}};
